<?php $pageTitle='Pedidos'; require __DIR__.'/_header.php';$status=trim($_GET['status']??'');$search=trim($_GET['q']??'');$sql='SELECT * FROM orders WHERE 1=1';$params=[];if($status){$sql.=' AND status=?';$params[]=$status;}if($search){$sql.=' AND (public_id LIKE ? OR customer_name LIKE ? OR whatsapp LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}$sql.=' ORDER BY id DESC LIMIT 250';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();?><form class="filter-bar"><input name="q" placeholder="Buscar pedido, cliente o teléfono" value="<?=h($search)?>"><select name="status"><option value="">Todos los estados</option><?php foreach(['received','awaiting_receipt','receipt_received','paid','preparing','ready','on_the_way','delivered','cancelled'] as $s):?><option <?=$status===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select><button class="btn small primary">Filtrar</button></form><section class="admin-card"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Fecha</th><th>Cliente</th><th>WhatsApp</th><th>Total</th><th>Entrega</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><?=h($o['public_id'])?></td><td><?=h($o['created_at'])?></td><td><?=h($o['customer_name'])?></td><td><?=h($o['whatsapp'])?></td><td><?=money((float)$o['total'])?></td><td><?=h($o['delivery_label'])?></td><td><span class="status-pill"><?=h($o['status'])?></span></td><td><a href="order.php?id=<?=$o['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>